          "before": "",
          "after": "// benitoite-derive:begin node\nimplement[T: Trait.Show] Trait.Show[Node[T]]\n  function show(x: Node[T]) -> String\n    return \"Node(\" + \"value: \" + Trait.Show.show(Node.value(x)) + \", children: \" + Trait.Show.show(Node.children(x)) + \")\"\n  end function\nend implement\n\nimplement[T: Trait.Order] Trait.Order[Node[T]]\n  function compare(x: Node[T], y: Node[T]) -> Trait.Ordering\n    bind deriveOrder0 <- Trait.Order.compare(x: Node.value(x), y: Node.value(y))\n    match deriveOrder0 with\n      case Trait.Ordering.Equal -> ()\n      case other -> return other\n    end match\n    bind deriveOrder1 <- Trait.Order.compare(x: Node.children(x), y: Node.children(y))\n    match deriveOrder1 with\n      case Trait.Ordering.Equal -> ()\n      case other -> return other\n    end match\n    return Trait.Ordering.Equal\n  end function\nend implement\n\nfunction derive_shrinkNode_0[T: equality](original: Node[T], value: T) -> Node[T]\n  return Node(..original, value: value)\nend function\n\nfunction derive_shrinkNode_1[T: equality](original: Node[T], value: List[Node[T]]) -> Node[T]\n  return Node(..original, children: value)\nend function\n\nfunction derive_shrinkNode_unique_1[T: equality](original: Node[T], steps: P.ShrinkStep[Node[T]]) -> P.ShrinkStep[Node[T]]\n  return match steps with\n    case P.ShrinkStep.Done -> P.ShrinkStep.Done\n    case P.ShrinkStep.Skip(next) -> P.ShrinkStep.Skip(lambda() return derive_shrinkNode_unique_1(original: original, steps: next()) end lambda)\n    case P.ShrinkStep.Yield(value, next) -> P.ShrinkStep.Skip(lambda()\n      if value = original then return derive_shrinkNode_unique_1(original: original, steps: next()) end if\n      return P.ShrinkStep.Yield(value, lambda() return derive_shrinkNode_unique_1(original: original, steps: next()) end lambda)\n    end lambda)\n  end match\nend function\n\nfunction derive_shrinkNode_replace_1[T: equality](element: P.Shrinker[T], original: List[Node[T]], index: Integer) -> P.ShrinkStep[List[Node[T]]]\n  return match List.get(xs: original, i: index) with\n    case Option.None -> P.ShrinkStep.Done\n    case Option.Some(child) -> P.ShrinkStep.Skip(lambda()\n      bind candidates <- P.Shrinker.candidates(block bind deriveFactory: P.Shrinker[Node[T]] <- shrinkNode(element: element)\n        deriveFactory end block)\n      return P.appendSteps(left: P.mapSteps(steps: derive_shrinkNode_unique_1(original: child, steps: candidates(child)), f: lambda(value) return List.concatenate(xs: List.append(xs: List.take(xs: original, n: index), x: value), ys: List.drop(xs: original, n: index + 1)) end lambda), right: lambda() return derive_shrinkNode_replace_1(element: element, original: original, index: index + 1) end lambda)\n    end lambda)\n  end match\nend function\n\nfunction derive_shrinkNode_steps_0[T: equality](element: P.Shrinker[T], recordValue: Node[T]) -> P.ShrinkStep[Node[T]]\n  return P.ShrinkStep.Skip(lambda()\n    return P.appendSteps(left: P.mapSteps(steps: block bind candidates <- P.Shrinker.candidates(P.shrinkList(element: P.Shrinker(candidates: lambda(value: Node[T]) return P.ShrinkStep.Done end lambda)))\n      candidates(Node.children(recordValue)) end block, f: derive_shrinkNode_1(original: recordValue, value: _)), right: lambda() return derive_shrinkNode_steps_1(element: element, recordValue: recordValue) end lambda)\n  end lambda)\nend function\n\nfunction derive_shrinkNode_steps_1[T: equality](element: P.Shrinker[T], recordValue: Node[T]) -> P.ShrinkStep[Node[T]]\n  return P.ShrinkStep.Skip(lambda()\n    return P.appendSteps(left: P.mapSteps(steps: block bind candidates <- P.Shrinker.candidates(element)\n      candidates(Node.value(recordValue)) end block, f: derive_shrinkNode_0(original: recordValue, value: _)), right: lambda() return derive_shrinkNode_steps_2(element: element, recordValue: recordValue) end lambda)\n  end lambda)\nend function\n\nfunction derive_shrinkNode_steps_2[T: equality](element: P.Shrinker[T], recordValue: Node[T]) -> P.ShrinkStep[Node[T]]\n  return P.ShrinkStep.Skip(lambda()\n    return P.appendSteps(left: P.mapSteps(steps: derive_shrinkNode_replace_1(element: element, original: Node.children(recordValue), index: 0), f: derive_shrinkNode_1(original: recordValue, value: _)), right: lambda() return P.ShrinkStep.Done end lambda)\n  end lambda)\nend function\n\nfunction derive_genNode_container1[T](element: P.Gen[T], budget: Integer, generator: Random.Generator, size: Integer) -> Pair[List[Node[T]], Pair[Integer, Random.Generator]]\n  bind count <- Random.nextInteger(generator: generator, low: 0, high: Integer.minimum(a: size, b: budget div 1) + 1)\n  return derive_genNode_container1_loop(element: element, budget: budget, generator: Pair.second(count), size: size, remaining: Pair.first(count), used: 0, acc: [])\nend function\n\nfunction derive_genNode_container1_loop[T](element: P.Gen[T], budget: Integer, generator: Random.Generator, size: Integer, remaining: Integer, used: Integer, acc: List[Node[T]]) -> Pair[List[Node[T]], Pair[Integer, Random.Generator]]\n  if remaining = 0 then return Pair(acc, Pair(used, generator)) end if\n  bind child: Pair[Node[T], Pair[Integer, Random.Generator]] <- derive_genNode_budget(element: element, budget: budget - used - (remaining - 1) * 1, generator: generator, size: size)\n  bind next <- List.append(xs: acc, x: Pair.first(child))\n  return derive_genNode_container1_loop(element: element, budget: budget, generator: Pair.second(Pair.second(child)), size: size, remaining: remaining - 1, used: used + Pair.first(Pair.second(child)), acc: next)\nend function\n\nfunction derive_genNode_budget[T](element: P.Gen[T], budget: Integer, generator: Random.Generator, size: Integer) -> Pair[Node[T], Pair[Integer, Random.Generator]]\n  bind deriveField0: Pair[T, Pair[Integer, Random.Generator]] <- block\n    bind deriveRun <- P.Gen.run(element)\n    bind derivePair <- deriveRun(generator: generator, size: size)\n    Pair(Pair.first(derivePair), Pair(0, Pair.second(derivePair)))\n  end block\n  bind deriveUsed0 <- 1 + Pair.first(Pair.second(deriveField0))\n  bind deriveField1: Pair[List[Node[T]], Pair[Integer, Random.Generator]] <- derive_genNode_container1(element: element, budget: budget - (deriveUsed0) - 0, generator: Pair.second(Pair.second(deriveField0)), size: size)\n  bind deriveUsed1 <- deriveUsed0 + Pair.first(Pair.second(deriveField1))\n  return Pair(Node(value: Pair.first(deriveField0), children: Pair.first(deriveField1)), Pair(deriveUsed1, Pair.second(Pair.second(deriveField1))))\nend function\n\n/// Generates Node with a shared recursive-node budget.\npublic function genNode[T](element: P.Gen[T]) -> P.Gen[Node[T]]\n  return P.Gen(run: lambda(generator: Random.Generator, size: Integer)\n    bind nonnegative <- Integer.maximum(a: size, b: 0)\n    bind budget <- 1 + Integer.minimum(a: nonnegative, b: 9223372036854775807 - 1)\n    bind result: Pair[Node[T], Pair[Integer, Random.Generator]] <- derive_genNode_budget(element: element, budget: budget, generator: generator, size: nonnegative)\n    return Pair(Pair.first(result), Pair.second(Pair.second(result)))\n  end lambda)\nend function\n\n/// Shrinks one field at a time in declaration order; cross-field conditions require a custom shrinker.\npublic function shrinkNode[T: equality](element: P.Shrinker[T]) -> P.Shrinker[Node[T]]\n  return P.Shrinker(candidates: lambda(value: Node[T])\n    return derive_shrinkNode_steps_0(element: element, recordValue: value)\n  end lambda)\nend function\n// benitoite-derive:end node\n"
